// warehouse-map · кейсы wm-01, wm-02, wm-03, wm-07, wm-08, wm-09, wm-10, wm-13 (.qa/tests/warehouse-map/) — только просмотр.
// wm-13 (#16c27b1d): числа зависят от реального склада — проверяем согласованность (строка = панель), а не конкретные значения.
// Реальная раскладка клиента: ничего не сохраняем (диалог «הוספת פריט» закрывается «ביטול»), все записи в Supabase заблокированы guard'ом.
import { test, expect } from '@playwright/test';
import { auth, side, openMap, guardWrites } from './_helpers';

test.use({ storageState: auth('admin') });

test.describe('warehouse-map — צפייה', () => {
  let violations: string[] = [];
  test.beforeEach(async ({ page }) => {
    violations = await guardWrites(page);
  });
  test.afterEach(() => {
    expect(violations, 'карта не должна ничего записывать').toEqual([]);
  });

  test('מקום עם מוצר משויך לא מוצג «ריק» #6a8f3153 @desktop @prod-safe', async ({ page }) => {
    await openMap(page, 'קומה 1');
    const cabinet = side(page).getByRole('button', { name: /^ארון .*\d+ מוצרים( משויכים)?$/ }).first();
    test.skip(!(await cabinet.count()), 'на карте нет шкафа с привязанным товаром');
    await expect(cabinet).not.toHaveAccessibleName(/ריק$/);
    await cabinet.click();
    await expect(side(page).getByRole('heading', { name: 'תכולת הארון' })).toBeVisible();
    const placed = side(page).getByRole('listitem').filter({ has: page.getByRole('button', { name: 'הסרה מהמקום' }) });
    await expect(placed.first()).toBeVisible();
    const n = await placed.count();
    for (let i = 0; i < n; i++) {
      const place = placed.nth(i).getByRole('button').first();
      await expect(place).not.toHaveAccessibleName(/ריק$/);
      await expect(placed.nth(i).getByRole('button', { name: 'העברה למיקום אחר' }).first()).toBeVisible();
    }
  });

  test('משטח — רשימת ארגזים, הוספת מוצר רק אחרי בחירת ארגז #6a8595c3 #6a85943e #6a730a70 @desktop @prod-safe', async ({ page }) => {
    await openMap(page, 'קומה 1');
    const pallet = side(page).getByRole('button', { name: /^משטח .* ארגזים? / }).first();
    test.skip(!(await pallet.count()), 'на «קומה 1» нет משטח с ארגזים');
    await pallet.click();
    const s = side(page);
    await expect(s.getByRole('heading', { name: 'תכולת המשטח' })).toBeVisible();
    await expect(s.getByRole('button', { name: /הוספת פריט למשטח/ })).toHaveCount(0);
    await expect(s.getByRole('button', { name: /^הוספת פריט/ })).toHaveCount(0);
    await expect(s.getByText(/מדף/)).toHaveCount(0);
    await s.getByRole('listitem').first().getByRole('button').first().click();
    await expect(s.getByRole('heading', { name: 'תכולת הארגז' })).toBeVisible();
    await expect(s.getByText('פריטים בארגז')).toBeVisible();
    await expect(s.getByRole('button', { name: 'הוספת פריט לארגז' })).toBeVisible();
  });

  test('אזור ארגזים בלי ארגזים — «אין ארגזים באזור», בלי הוספת מוצר #6a8595c3 @desktop @prod-safe', async ({ page }) => {
    await openMap(page, 'המחסן שלנו');
    const area = side(page).getByRole('button', { name: /^.+ 0 אזור ארגזים ריק$/ }).first();
    test.skip(!(await area.count()), 'нет пустой אזור ארגזים без ארגזים');
    await area.click();
    const s = side(page);
    await expect(s.getByRole('heading', { name: 'תכולת אזור הארגזים' })).toBeVisible();
    await expect(s.getByText('אין ארגזים באזור')).toBeVisible();
    await expect(s.getByText('מוצרים מאוחסנים בתוך ארגזים — הוסיפו ארגז במפה כדי לאחסן כאן.')).toBeVisible();
    await expect(s.getByRole('button', { name: /הוספת פריט/ })).toHaveCount(0);
  });

  test('«הוספת פריט» פותח דיאלוג קליטה עם מוצר, מקום וכמות; ביטול סוגר #6a71ef21 #6a859245 @desktop @prod-safe', async ({ page }) => {
    await openMap(page);
    await page.getByRole('button', { name: 'הוספת פריט', exact: true }).click();
    const d = page.getByRole('dialog');
    await expect(d.getByText('הוספת פריט למלאי')).toBeVisible();
    await expect(d.getByText('בחרו מוצר וכמות; המקום אינו חובה')).toBeVisible();
    await expect(d.getByRole('combobox', { name: 'מוצר' })).toBeVisible();
    await expect(d.getByRole('button', { name: 'זיהוי מוצר מתמונה' })).toBeVisible();
    const place = d.getByLabel('מקום היעד');
    await expect(place).toBeVisible();
    await expect(place.locator('option', { hasText: 'ללא מקום — לשיוך בהמשך' })).toHaveCount(1);
    await expect.poll(() => place.locator('option').count(), { timeout: 10_000 }).toBeGreaterThan(1);
    await expect(d.getByLabel('כמות')).toBeVisible();
    await expect(d.getByText('לא חובה — נשמרת ביומן התנועות')).toBeVisible();
    await expect(d.getByRole('button', { name: 'הוספה' })).toBeVisible();
    await d.getByRole('button', { name: 'ביטול' }).click();
    await expect(page.getByRole('dialog')).toHaveCount(0);
  });

  test('מפה מרובת קומות: קנבס, זום, החלפת קומה #6a5cb979 @desktop @prod-safe', async ({ page }) => {
    await openMap(page);
    await expect(page.getByRole('application', { name: 'קנבס המחסן' })).toBeVisible();
    for (const b of ['הגדלה', 'הקטנה', 'התאמה למסך']) await expect(page.getByRole('button', { name: b }).first()).toBeVisible();
    const tabs = page.getByRole('tablist', { name: 'קומות המחסן' }).getByRole('tab');
    const n = await tabs.count();
    expect(n).toBeGreaterThan(0);
    for (let i = 0; i < n; i++) {
      await tabs.nth(i).click();
      await expect(tabs.nth(i)).toHaveAttribute('aria-selected', 'true');
      await expect(side(page).getByText('פריסה')).toBeVisible();
      await expect(side(page).getByText('יחידות').first()).toBeVisible();
    }
  });

  test('חיפוש במפה מסמן מקומות תואמים #6a5cb979 @desktop @prod-safe', async ({ page }) => {
    await openMap(page, 'קומה 1');
    await page.getByRole('textbox', { name: 'חיפוש במפה' }).fill('ארון');
    await expect(side(page).getByText('המקומות המסומנים במפה הם אלה שתואמים את החיפוש. הקישו על אחד מהם.')).toBeVisible();
    await expect(side(page).getByRole('button').nth(1)).toBeVisible();
    await page.getByRole('textbox', { name: 'חיפוש במפה' }).fill('');
    await expect(side(page).getByText('הקישו על ארון, מדף, משטח או ארגז במפה כדי לראות אילו פריטים מונחים בו ובאיזו כמות.')).toBeVisible();
  });

  test('יומן תנועות — סינון לפי סוג תנועה #6a5cb979 @desktop @prod-safe', async ({ page }) => {
    await openMap(page);
    await expect(page.getByText('יומן תנועות')).toBeVisible();
    await expect(page.getByText('כל תנועה שנעשתה, לפי סדר זמן')).toBeVisible();
    const filters = page.getByRole('tablist', { name: 'סינון לפי סוג תנועה' });
    for (const t of ['קליטה', 'העברה', 'ליקוט', 'החזרות', 'הכל']) {
      await filters.getByRole('tab', { name: t, exact: true }).click();
      await expect(filters.getByRole('tab', { name: t, exact: true })).toHaveAttribute('aria-selected', 'true');
    }
  });

  // ---- #16c27b1d: строка «משטח» в «האחסון במחסן» считает ארגזים на нём ----
  const PALLET_ROW = /^(משטח \S+) (\d+) (.*)$/;
  /** Доступные имена кнопок сайдбара (как их видит a11y-дерево, с пробелами между частями). */
  async function buttonNames(page: import('@playwright/test').Page, prefix: RegExp) {
    const snap = await side(page).ariaSnapshot();
    return [...snap.matchAll(/button "([^"]+)"/g)].map((m) => m[1].replace(/\s+/g, ' ').trim()).filter((n) => prefix.test(n));
  }
  async function palletRows(page: import('@playwright/test').Page) {
    return (await buttonNames(page, /^משטח /)).map((n) => n.match(PALLET_ROW)).filter(Boolean)
      .map((m) => ({ full: m![0], name: m![1], qty: Number(m![2]), rest: m![3] }));
  }

  test('שורת משטח: «ריק» רק כשאין מלאי; מספר בשורה = סכום הארגזים בפאנל, «בארגזים» #16c27b1d @desktop @prod-safe', async ({ page }) => {
    test.setTimeout(120_000);
    let checkedBoxes = 0;
    for (const floor of ['קומה 1', 'קומה 2']) {
      await openMap(page, floor);
      const rows = await palletRows(page);
      for (const r of rows) {
        if (r.qty === 0) expect(r.rest, `${floor} · ${r.name}: 0 → «ריק»`).toMatch(/ריק$/);
        else expect(r.rest, `${floor} · ${r.name}: ${r.qty} → не «ריק»`).not.toMatch(/ריק$/);
      }
      for (const r of rows.filter((x) => x.qty > 0 && /בארגזים/.test(x.rest))) {
        await openMap(page, floor);
        await side(page).getByRole('button', { name: r.full, exact: true }).click();
        await expect(side(page).getByRole('heading', { name: 'תכולת המשטח' })).toBeVisible();
        await expect(side(page).getByText('ארגזים על המשטח')).toBeVisible();
        const boxes = await buttonNames(page, /^ארגז /);
        expect(boxes.length, 'в панели есть ארגזים').toBeGreaterThan(0);
        const sum = boxes.map((b) => Number((b.match(/ (\d+)$/) || [])[1] || 0)).reduce((a, b) => a + b, 0);
        expect(sum, `${floor} · ${r.name}: строка ${r.qty} = сумма ארגזים в панели`).toBe(r.qty);
        checkedBoxes++;
      }
    }
    if (checkedBoxes === 0) test.info().annotations.push({ type: 'note', description: 'нет משטח с остатком «בארגזים» — сверка строки с панелью не выполнялась (правило «ריק» проверено)' });
  });

  test('חיפוש משטח מציג את אותה כמות כמו בשורה (כולל ארגזים) #16c27b1d @desktop @prod-safe', async ({ page }) => {
    await openMap(page, 'קומה 2');
    const row = (await palletRows(page)).find((r) => r.qty > 0 && /בארגזים/.test(r.rest));
    test.skip(!row, 'на «קומה 2» нет משטח с остатком «בארגזים»');
    await page.getByRole('textbox', { name: 'חיפוש במפה' }).fill(row!.name);
    const hit = side(page).getByRole('button', { name: new RegExp(`^${row!.name} \\d+ `) }).first();
    await expect(hit).toBeVisible({ timeout: 10_000 });
    const found = (await palletRows(page)).find((r) => r.name === row!.name);
    expect(found?.qty, 'количество в результате поиска').toBe(row!.qty);
    await expect(hit).not.toHaveAccessibleName(/ריק$/);
  });

  test('מפת המחסן במובייל — בלי גלילה אופקית #6a5cb979 @mobile @prod-safe', async ({ page }) => {
    await page.goto('/warehouse/map');
    await expect(page.getByRole('heading', { name: 'האחסון במחסן' })).toBeVisible({ timeout: 30_000 });
    await expect(page.getByRole('application', { name: 'קנבס המחסן' })).toBeVisible();
    const [sw, iw] = await page.evaluate(() => [document.documentElement.scrollWidth, window.innerWidth]);
    expect(sw).toBeLessThanOrEqual(iw);
  });
});
